mod tests {
    use super::*;
    use std::collections::BTreeMap;

    const INVALID_REL_PATHS: &[&str] = &[
        "", "/absolute.rs", ".", "..", "../escape.rs", "src/../escape.rs",
        "src/./lib.rs", "src//lib.rs", "src/", "src\\lib.rs", "src/\0lib.rs",
