        let json = serde_json::to_string(&c).unwrap();
        assert_eq!(json, format!("\"{}\"", c.0.hyphenated()));
        assert_eq!(serde_json::from_str::<ChangeId>(&json).unwrap(), c);
        assert_eq!(
